using System.Security.Claims;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using RaceDay.Api.Data;using RaceDay.Api.DTOs;using RaceDay.Api.Models;
namespace RaceDay.Api.Controllers;
[ApiController][Route("api")]
public class ResultsController(RaceDayDbContext db):ControllerBase{
 int UserId=>int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);
 [Authorize(Roles="Organiser")][HttpPost("enrolments/{enrolmentId:int}/results")]public async Task<IActionResult> Create(int enrolmentId,ResultRequest r){var en=await db.Enrolments.Include(x=>x.Category).ThenInclude(x=>x!.Event).FirstOrDefaultAsync(x=>x.EnrolmentID==enrolmentId);if(en==null)return NotFound();if(en.Category!.Event!.OrganiserID!=UserId)return Forbid();if(await db.Results.AnyAsync(x=>x.EnrolmentID==enrolmentId))return Conflict(new{message="Result already exists"});var result=new Result{EnrolmentID=enrolmentId,FinishTime=r.FinishTime,Position=r.Position};db.Results.Add(result);await db.SaveChangesAsync();return Created("",result);}
 [Authorize(Roles="Participant")][HttpGet("results/me")]public async Task<IActionResult> Mine(){var rows=await db.Results.Include(x=>x.Enrolment).ThenInclude(x=>x!.Category).ThenInclude(x=>x!.Event).Where(x=>x.Enrolment!.UserID==UserId).ToListAsync();var output=new List<object>();foreach(var r in rows){var eventId=r.Enrolment!.Category!.EventID;var finishers=await db.Results.CountAsync(x=>x.Enrolment!.Category!.EventID==eventId);output.Add(new{r.ResultID,r.FinishTime,r.Position,r.Status,eventName=r.Enrolment.Category.Event!.Name,eventDate=r.Enrolment.Category.Event.EventDate,categoryName=r.Enrolment.Category.Name,totalFinishers=finishers});}return Ok(output);}
 [HttpGet("events/{eventId:int}/results")]public async Task<IActionResult> EventResults(int eventId){if(!await db.Events.AnyAsync(x=>x.EventID==eventId))return NotFound();return Ok(await db.Results.Include(x=>x.Enrolment).ThenInclude(x=>x!.User).Include(x=>x.Enrolment).ThenInclude(x=>x!.Category).Where(x=>x.Enrolment!.Category!.EventID==eventId).ToListAsync());}
 [Authorize(Roles="Organiser")][HttpPut("results/{id:int}")]public async Task<IActionResult> Update(int id,ResultRequest r){var x=await db.Results.Include(x=>x.Enrolment).ThenInclude(x=>x!.Category).ThenInclude(x=>x!.Event).FirstOrDefaultAsync(x=>x.ResultID==id);if(x==null)return NotFound();if(x.Enrolment!.Category!.Event!.OrganiserID!=UserId)return Forbid();x.FinishTime=r.FinishTime;x.Position=r.Position;await db.SaveChangesAsync();return Ok(x);}
}
